import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Мониторинг и журнал событий","description":"","frontmatter":{"pageId":"admins/monitoring","contentRevision":5},"headers":[],"relativePath":"ru/admins/monitoring.md","filePath":"ru/admins/monitoring.md"}'),o={name:"ru/admins/monitoring.md"};function s(n,a,l,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="мониторинг-и-журнал-событии" tabindex="-1">Мониторинг и журнал событий <a class="header-anchor" href="#мониторинг-и-журнал-событии" aria-label="Permalink to &quot;Мониторинг и журнал событий&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>GET /health проверяет доступность процесса; /metrics предоставляет метрики. Настрой сетевое ограничение и сбор с доверенного узла. Административный /status даёт служебное состояние; журнал /actions помогает связать изменения с оператором.</p><p>SSE GET /api/admin/events использует идентификатор epoch:seq. Передай Last-Event-ID при переподключении. gap означает, что события потеряны из-за рестарта/переполнения: перечитай текущее состояние, не выводи его только из неполного feed. По умолчанию буфер 1000, ping каждые 15 секунд.</p><p>Следи за свободным диском, возрастом последней успешной копии, отказами входа, сохранений, доставок и долгими live-сессиями. Сигнал «процесс жив» не заменяет проверку чтения/записи колонии.</p><h2 id="monitor-layers" tabindex="-1">Три уровня наблюдения <a class="header-anchor" href="#monitor-layers" aria-label="Permalink to &quot;Три уровня наблюдения {#monitor-layers}&quot;">​</a></h2><p>Разделяй доступность процесса, корректность приложения и возможность восстановления. /health отвечает на первый вопрос. Статус/метрики, отказы входа/сейва, очередь и длительность сессий — на второй. Возраст успешного backup и периодическое изолированное восстановление — на третий.</p><p>Сравнивай тенденции диска с реальным saves.diskBytes; рост старых версий и внешних ZIP может иметь разные причины. Сохраняй время/версию и audit перед вмешательством. Не публикуй метрики с приватными именами/токенами и ограничь публичный /metrics сетью.</p><h2 id="sse-gap" tabindex="-1">Как обрабатывать пропуск SSE <a class="header-anchor" href="#sse-gap" aria-label="Permalink to &quot;Как обрабатывать пропуск SSE {#sse-gap}&quot;">​</a></h2><p>Храни последний epoch:seq после обработанного события. При reconnect отправляй Last-Event-ID. Gap означает, что локального журнала уже недостаточно: перечитай нужные status/списки, обнови экран и продолжи новый поток. Не придумывай недостающие события и не исполняй мутации из повторного уведомления.</p><p>Пинг подтверждает жизнь потока, не факт новой сделки. Личные сообщения/кошельки/посылки и ещё не высаженные рейды намеренно отсутствуют; для расследования нужны авторизованные чтения нужной сущности, а не попытка восстановить её из публичного feed.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Feed намеренно не содержит приватный чат, кошельки, посылки и ещё не высадившиеся рейды. Не включай токены/полные сейвы в метрики и общие логи. /metrics публичен на уровне приложения — ограничивай доступ сетью.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./discord">Discord-бот</a></li><li><a href="./troubleshooting">Проблемы администратора</a></li><li><a href="./api">Справочник REST API</a></li></ul>',16)])])}const u=e(o,[["render",s]]);export{m as __pageData,u as default};
